import{_ as n,o as t,c as i,a1 as e}from"./chunks/framework.DxqwKiYY.js";const s="/pelatihan-webgis-big/assets/image1.0-vGh-9Y.png",r="/pelatihan-webgis-big/assets/image2.B_rkaRAq.png",g="/pelatihan-webgis-big/assets/image3.BqEP8I_F.png",p="/pelatihan-webgis-big/assets/image.C8ljW0eZ.png",m="/pelatihan-webgis-big/assets/image%201.BYzOPYHE.png",o="/pelatihan-webgis-big/assets/image6.CKdk6HHD.png",l="/pelatihan-webgis-big/assets/image%202.B2e9Gzy8.png",d="/pelatihan-webgis-big/assets/image8.DgsxMoP2.png",u="/pelatihan-webgis-big/assets/image9.8Od-2f4R.png",k="/pelatihan-webgis-big/assets/image10.CCoZQaxL.png",b="/pelatihan-webgis-big/assets/image11.CLcbQx0f.png",h="/pelatihan-webgis-big/assets/image12.CCkQKVds.png",c="/pelatihan-webgis-big/assets/image13.Blsnfel_.png",D="/pelatihan-webgis-big/assets/image14.VvTTTOIW.png",_="/pelatihan-webgis-big/assets/image%203.P57DxxFV.png",f="/pelatihan-webgis-big/assets/image%204.PnKYzhyL.png",w="/pelatihan-webgis-big/assets/image%205.BqUfcYS_.png",y="/pelatihan-webgis-big/assets/image18.Dhmh41iR.png",j="/pelatihan-webgis-big/assets/image%206.CaHAtcWO.png",B=JSON.parse('{"title":"Visualisasi Data 2D dan 3D","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Visualisasi Data 2D dan 3D.md","filePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Visualisasi Data 2D dan 3D.md"}'),C={name:"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Visualisasi Data 2D dan 3D.md"};function T(S,a,P,V,v,x){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="visualisasi-data-2d-dan-3d" tabindex="-1">Visualisasi Data 2D dan 3D <a class="header-anchor" href="#visualisasi-data-2d-dan-3d" aria-label="Permalink to &quot;Visualisasi Data 2D dan 3D&quot;">​</a></h1><h2 id="menambahkan-data-2d" tabindex="-1"><strong>Menambahkan Data 2D</strong> <a class="header-anchor" href="#menambahkan-data-2d" aria-label="Permalink to &quot;**Menambahkan Data 2D**&quot;">​</a></h2><ol><li><p>Tahap pertama buat file dengan nama <strong>addDataVektor2D.jsx</strong> pada folder <strong>components</strong>.</p><p><img src="'+s+'" alt=""></p></li><li><p>Kemudian pada tahap kedua buat fungsi berupa <strong>addDataVektor2D</strong> digunakan sebagai tempat utama untuk menjalankan seluruh proses penambahan data vektor 2D. Kemudian tambahkan parameter <strong>viewer</strong>, <strong>opsi</strong> yang digunakan pengaturan data yang ingin ditampilkan, serta parameter <strong>selesai</strong> yang dijalankan setelah data berhasil dimuat.</p><p><img src="'+r+'" alt=""></p></li><li><p>Tahap ketiga didalam function tersebut tambahkan variabel c<strong>onst Cesium = window.Cesium;</strong> yang digunakan untuk mengambil objek Cesium yang sudah tersedia di halaman.</p><p><img src="'+g+'" alt=""></p></li><li><p>Tahap keempat buat variabel yang berfungsi digunakan untuk mengambil berbagai konfigurasi dari parameter opsi, seperti URL sumber data, nama layer, warna dan outline garis, ketebalan garis, pengaturan agar data mengikuti terrain, serta opsi untuk mengarahkan kamera secara otomatis ke lokasi data.</p><p><img src="'+p+'" alt="image.png"></p></li><li><p>Pada tahap kelima buat kondisi <strong>if</strong> untuk memeriksa apakah <strong>url</strong> tersedia, dan jika tidak tersedia maka fungsi selesai akan dijalankan dengan nilai <strong>null</strong> sebelum proses dihentikan agar proses dihentikan jika tanpa data.</p><p><img src="'+m+'" alt="image.png"></p></li><li><p>Tahap keenam buat fungsi untuk memuat data GeoJSON dari url menggunakan <strong>Cesium.GeoJsonDataSource</strong>, dengan opsi parameter <strong>clampToGround</strong> untuk menentukan apakah data mengikuti atau menempel pada permukaan terrain.</p><p><img src="'+o+'" alt=""></p></li><li><p>Selanjutnya tahap ketujuh buat fungsi <strong>.then()</strong> yang akan dijalankan setelah proses memuat GeoJSON berhasil. Data yang berhasil dimuat kemudian disimpan dalam variabel <strong>dataSource</strong>.</p><p><img src="'+l+'" alt="image.png"></p></li><li><p>Pada fungsi <strong>.then</strong> tambahkan fungsi untuk memberikan nama pada data yang telah dimuat melalui <strong>dataSource.name = nama</strong>, kemudian menambahkan data tersebut dengan <strong>viewer.dataSources.add(dataSource)</strong> agar dapat ditampilkan pada peta.</p><p><img src="'+d+'" alt=""></p></li><li><p>Kemudian tambahkan fungsi untuk melakukan perulangan pada seluruh objek yang terdapat di dalam <strong>dataSource</strong>, sehingga setiap data dapat diperiksa dan diatur satu per satu.</p><p><img src="'+u+'" alt=""></p></li><li><p>Selanjutnya pada fungsi <strong>dataSource</strong> tersebut tambahkan kondisi <strong>if</strong> untuk memeriksa apakah entity merupakan data berbentuk garis (polyline), kemudian mengatur warna dan outline garis, menentukan ketebalan garis, serta membuat garis mengikuti permukaan terrain.</p><p><img src="'+k+'" alt=""></p></li><li><p>Selanjutnya buat kondisi <strong>if</strong> untuk pengecekan terhadap data polygon dengan membuat variabel untuk menngatur tipe klasifikasi atau <strong>classificationType</strong> menjadi <strong>Cesium.ClassificationType.TERRAIN</strong> sehingga jika data polygon dapat ditampilkan dan mengikuti klasifikasi permukaan terrain pada peta 3D.</p><p><img src="'+b+'" alt=""></p></li><li><p>Tahap terakhir buat fungsi dengan kondisi <strong>if</strong> yang digunakan untuk mengarahkan kamera secara otomatis ke lokasi data apabila otomatisZoom aktif, kemudian menjalankan fungsi selesai dengan mengirimkan dataSource sebagai tanda bahwa proses pemuatan dan penambahan data telah selesai.</p><p><img src="'+h+'" alt=""></p></li></ol><h2 id="integrasi-tampilan-data-2d-dengan-cesium-viewer" tabindex="-1"><strong>Integrasi Tampilan Data 2D dengan Cesium Viewer</strong> <a class="header-anchor" href="#integrasi-tampilan-data-2d-dengan-cesium-viewer" aria-label="Permalink to &quot;**Integrasi Tampilan Data 2D dengan Cesium Viewer**&quot;">​</a></h2><ol><li><p>Tahap pertama, masukan data geojson yang akan ditampilkan kedalam folder <strong>public</strong>, kemudian pilih folder <strong>data</strong>.</p><p><img src="'+c+'" alt=""></p></li><li><p>Tahap kedua buka file CesiumViewer.jsx kemudian pada <strong>function addContent3D(viewer) {</strong> tambahkan variabel berupa <strong>const Cesium = window.Cesium</strong>.</p><p><img src="'+D+'" alt=""></p></li><li><p>Tahap ketiga pada <strong>function (gedung3D) {</strong> yang terdapat dalam <strong>function addContent3D</strong> tambahkan fungsi <strong>addDataVektor2D</strong> untuk memuat data GeoJSON jaringan jalan ke dalam peta Cesium, dengan tampilan garis berwarna kuning, ketebalan 4, dan tanpa mengarahkan kamera secara otomatis ke lokasi data.</p><p><img src="'+_+'" alt="image.png"></p></li><li><p>Selanjutnya tambahkan data berupa batas administrasi dengan cara yang sama.</p><p><img src="'+f+'" alt="image.png"></p></li><li><p>Tahap keempat buat panggilan untuk menerima data jaringan jalan yang telah berhasil dimuat sebelumnya, kemudian menambahkan data tersebut ke dalam <strong>addPanelLayer3D</strong> dengan nama <strong>Jaringan Jalan</strong> dan <strong>Batas Administrasi</strong> agar dapat dikelola dan ditampilkan bersama layer 3D lainnya pada panel layer.</p><p><img src="'+w+'" alt="image.png"></p></li><li><p>Tahap terakhir pastikan addDataVektor2D sudah terimport dalam <strong>CesiumViewer.jsx</strong>.</p><p><img src="'+y+'" alt=""></p></li><li><p>Hasil tampilan visulisasi data 2D berupa data jaringan jalan dan batas adminsitrasi berwarna kuning dengan data 3D bangunan.</p><p><img src="'+j+'" alt="image.png"></p></li></ol>',5)])])}const I=n(C,[["render",T]]);export{B as __pageData,I as default};
